import { test } from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('exportCsv: returns CSV string starting with header', () => {
  const result = exportCsv([]);

  assert(result.includes('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due'));
  assert(result.startsWith('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due'));
});

test('exportCsv: ends with newline', () => {
  const result = exportCsv([]);

  assert(result.endsWith('\n'));
});

test('exportCsv: exports single invoice', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  const result = exportCsv([invoice]);

  assert(result.includes('C-001'));
  assert(result.includes('Northwind Studio'));
  assert(result.includes('2025-02-14'));
  assert(result.includes('issued'));
});

test('exportCsv: includes invoice number', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  const result = exportCsv([invoice]);

  assert(result.includes(invoice.number));
});

test('exportCsv: includes customer name', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  const result = exportCsv([invoice]);

  assert(result.includes('Northwind Studio'));
});

test('exportCsv: formats amounts as euros with 2 decimals', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  const result = exportCsv([invoice]);

  // STICKER: 50 cents + VAT = 61 cents = 0.61 euros
  assert(result.includes('0.50'));
  assert(result.includes('0.61'));
});

test('exportCsv: does not use currency symbol', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  const result = exportCsv([invoice]);

  assert(!result.includes('€'));
});

test('exportCsv: does not use thousands separator', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  const result = exportCsv([invoice]);

  // LOGO-PACK: 120000 cents = 1200 euros
  assert(result.includes('1200.00'));
  assert(!result.includes('1,200'));
});

test('exportCsv: escapes fields with commas', () => {
  const mockInvoice = {
    number: 'TEST-001',
    customerId: 'C-001',
    issueDate: '2025-02-14',
    dueDate: '2025-03-16',
    status: 'issued',
    lines: [{ qty: 10, unitPrice: 9500, vatRate: 21 }],
  };

  const result = exportCsv([mockInvoice]);

  // Check that customer name with comma is quoted
  assert(result.includes('"'));
});

test('exportCsv: handles unknown customer gracefully', () => {
  const mockInvoice = {
    number: 'TEST-001',
    customerId: 'UNKNOWN',
    issueDate: '2025-02-14',
    dueDate: '2025-03-16',
    status: 'issued',
    lines: [{ qty: 10, unitPrice: 9500, vatRate: 21 }],
  };

  const result = exportCsv([mockInvoice]);

  assert(result.includes('UNKNOWN'));
});

test('exportCsv: includes all required columns', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  const result = exportCsv([invoice]);
  const lines = result.trim().split('\n');

  assert.equal(lines.length, 2); // Header + 1 invoice

  const headerFields = lines[0].split(',');
  assert.deepEqual(headerFields, [
    'number',
    'customer',
    'issueDate',
    'dueDate',
    'status',
    'subtotal',
    'discount',
    'vat',
    'total',
    'due',
  ]);
});

test('exportCsv: exports multiple invoices', () => {
  let invoice1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  let invoice2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-15',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });

  assert.equal(invoice1Result.ok, true);
  assert.equal(invoice2Result.ok, true);

  const invoice1 = issueInvoice(invoice1Result.value, []).value;
  const invoice2 = issueInvoice(invoice2Result.value, ['2025-0001']).value;

  const result = exportCsv([invoice1, invoice2]);
  const lines = result.trim().split('\n');

  assert.equal(lines.length, 3); // Header + 2 invoices
  assert(lines[1].includes('Northwind Studio'));
  assert(lines[2].includes('Blue Fern Bakery'));
});

test('exportCsv: includes invoice status', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  let invoice = issueInvoice(invoiceResult.value, []).value;

  const result = exportCsv([invoice]);

  assert(result.includes('issued'));
});

test('exportCsv: includes dates correctly', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  const result = exportCsv([invoice]);

  assert(result.includes('2025-02-14'));
  assert(result.includes(invoice.dueDate));
});

test('exportCsv: calculates due amount correctly', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  let invoice = issueInvoice(invoiceResult.value, []).value;

  const paymentResult = recordPayment(invoice, { amount: 50000, date: '2025-03-01' });
  assert.equal(paymentResult.ok, true);
  invoice = paymentResult.value;

  const result = exportCsv([invoice]);

  // Total is 114950, paid 50000, due is 64950 = 649.50
  assert(result.includes('649.50'));
});

test('exportCsv: includes discount in export', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  const result = exportCsv([invoice]);

  // Discount: 95000 * 10% = 9500 = 95.00
  assert(result.includes('95.00'));
});

test('exportCsv: includes VAT in export', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  const result = exportCsv([invoice]);

  // VAT: 95000 * 21% = 19950 = 199.50
  assert(result.includes('199.50'));
});

test('exportCsv: CSV can be parsed correctly', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  const result = exportCsv([invoice]);
  const lines = result.trim().split('\n');

  assert.equal(lines.length, 2);

  const headerFields = lines[0].split(',');
  assert.equal(headerFields.length, 10);

  // Parse data line - be careful with CSV parsing
  const dataLine = lines[1];
  assert(dataLine.includes(','));
});

test('exportCsv: handles draft invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const result = exportCsv([invoice]);

  assert(result.includes('draft'));
});

test('exportCsv: handles empty invoice list', () => {
  const result = exportCsv([]);

  const lines = result.trim().split('\n');
  assert.equal(lines.length, 1); // Just header
  assert(lines[0].includes('number,customer,issueDate'));
});

test('exportCsv: properly formats zero amounts', () => {
  const mockInvoice = {
    number: 'TEST-001',
    customerId: 'C-001',
    issueDate: '2025-02-14',
    dueDate: '2025-03-16',
    status: 'issued',
    lines: [],
  };

  const result = exportCsv([mockInvoice]);

  assert(result.includes('0.00'));
});

